import { NewsService, shanghaiDate } from '../../services/news/service.ts';
import { readNewsSources } from '../../services/news/sources.ts';
import { mkdir, mkdtemp, writeFile, readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { performance } from 'node:perf_hooks';
const parent=path.resolve('node_modules/.cache');await mkdir(parent,{recursive:true});const base=await mkdtemp(path.join(parent,'news07-live-')); 
const original=globalThis.fetch, requests=[], snapshots=[];let round=1;
globalThis.fetch=async(input,init)=>{const url=String(input),startedAt=new Date().toISOString(),start=performance.now(),entry={round,url,startedAt};requests.push(entry);try{const res=await original(input,init);entry.status=res.status;entry.finishedAt=new Date().toISOString();entry.durationMs=Math.round(performance.now()-start);const id=requests.indexOf(entry)+1;const clone=res.clone();snapshots.push((async()=>{const limit=/\.pdf(?:[?#]|$)/iu.test(url)?10*1024*1024:2*1024*1024,reader=clone.body.getReader(),chunks=[];let size=0;for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>limit){await reader.cancel();throw Error('snapshot size limit');}chunks.push(value);}const bytes=Buffer.concat(chunks);entry.bytes=bytes.length;entry.sha256=createHash('sha256').update(bytes).digest('hex');entry.snapshot=`response-${id}.bin`;await writeFile(path.join(base,entry.snapshot),bytes);})().catch(e=>{entry.snapshotError=String(e)}));return res;}catch(e){entry.finishedAt=new Date().toISOString();entry.durationMs=Math.round(performance.now()-start);entry.error=String(e);throw e;}};
const files=['services/news/service.ts','services/news/sources.ts','services/news/research-sources.ts','services/news/normalize.ts','services/news/types.ts','app/pages/NewsPage.tsx'];const hashes={};for(const f of files)hashes[f]=createHash('sha256').update(await readFile(f)).digest('hex');
// Complete source responses and excerpts remain only in the ignored local cache.
const result={startedAt:new Date().toISOString(),hashes,base,rounds:[],providerCalls:0};
async function run(root){const svc=new NewsService({root,clock:()=>new Date(),readSources:readNewsSources,aiEnabled:false,providerFactory:async()=>{result.providerCalls++;throw Error('provider forbidden')}});const start=performance.now();await svc.ensure();let view;for(let i=0;i<600;i++){view=await svc.today();if(Object.values(view.edition?.sections||{}).every(s=>s.status!=='running'))break;await new Promise(r=>setTimeout(r,250));}if(Object.values(view.edition?.sections||{}).some(s=>s.status==='running'))throw Error('settle timeout');return {svc,view,durationMs:Math.round(performance.now()-start)};}
try{const a=await run(path.join(base,'round1'));const count=requests.length,before=JSON.stringify(a.view.edition);await a.svc.ensure();const after=await a.svc.today();result.cache={requestsBefore:count,requestsAfter:requests.length,unchanged:before===JSON.stringify(after.edition)};result.rounds.push({durationMs:a.durationMs,view:a.view});const now=new Date(),today=shanghaiDate(now),yesterday=new Date(Date.parse(today+'T00:00:00Z')-86400000).toISOString().slice(0,10),root=path.join(base,'round2'),part=a.view.edition?.sections.fmcg;await mkdir(path.join(root,'state/news'),{recursive:true});if(part?.items.length){const fixture={schemaVersion:1,date:yesterday,updatedAt:now.toISOString(),sections:{fmcg:{...part,status:'source_only'}}};await writeFile(path.join(root,'state/news',yesterday+'.json'),JSON.stringify(fixture,null,2));result.history={kind:'本轮实采构造的隔离历史',date:yesterday,count:part.items.length};}else result.history={kind:'BLOCKED：首轮无快消条目',count:0};round=2;const b=await run(root);result.rounds.push({durationMs:b.durationMs,view:b.view});}catch(e){result.error=String(e)}finally{await Promise.all(snapshots);result.finishedAt=new Date().toISOString();result.requests=requests;await writeFile(path.join(base,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify({base,startedAt:result.startedAt,finishedAt:result.finishedAt,error:result.error,cache:result.cache,history:result.history,providerCalls:result.providerCalls,rounds:result.rounds.map(x=>({durationMs:x.durationMs,sections:Object.fromEntries(Object.entries(x.view.edition?.sections||{}).map(([k,v])=>[k,{status:v.status,count:v.items.length,sources:v.sources,shortageReasons:v.shortageReasons}]))})),requests:requests.map(({round,url,status,error,durationMs,bytes})=>({round,url,status,error,durationMs,bytes}))},null,2));}
